import type { VerticalTabBarSectionProps } from "../vertical-tab-bar.types";

import React, { forwardRef, useRef } from "react";
import { clsx } from "clsx";
import { Accordion } from "@components/accordion";
import { useUniqueId } from "@system";

import { useTabBar } from "../../tab-bar/hooks/use-tab-bar";
import { VerticalTabBarClasses } from "../vertical-tab-bar.styles";

export const VerticalTabBarSection = forwardRef<HTMLDivElement, VerticalTabBarSectionProps>(
  (
    {
      className,
      children,
      title,
      defaultExpanded = false,
      expanded,
      onExpandedChange,
      alwaysExpanded = false,
      ...props
    },
    ref,
  ) => {
    const contentRef = useRef<HTMLDivElement>(null);
    const headerRef = useRef<HTMLButtonElement>(null);
    const sectionId = useUniqueId("vertical-tab-bar-section");
    const { activeTab } = useTabBar();

    const getTabValues = (nodes: React.ReactNode): string[] => {
      return React.Children.toArray(nodes).flatMap((node) => {
        if (!React.isValidElement(node)) {
          return [];
        }
        if (node.props.value) {
          return [node.props.value];
        }
        if (node.props.children) {
          return getTabValues(node.props.children);
        }
      });
    };

    const tabValues = getTabValues(children);
    const isTabActive = tabValues.includes(activeTab);

    return (
      <Accordion
        ref={ref}
        className={clsx(VerticalTabBarClasses.section, className)}
        sectionsInitiallyOpen="determined"
        size="sm"
        {...props}
      >
        <Accordion.Section
          isExpanded={expanded}
          isInitialOpen={alwaysExpanded || defaultExpanded}
          onValueChange={onExpandedChange}
        >
          <Accordion.Header
            ref={headerRef}
            as="div"
            className={clsx(
              VerticalTabBarClasses.sectionHeader,
              isTabActive && VerticalTabBarClasses.sectionHeaderActive,
              alwaysExpanded && VerticalTabBarClasses.sectionHeaderAlwaysOpen,
            )}
            data-active-tab={isTabActive}
            disabled={alwaysExpanded}
            id={sectionId}
          >
            {!alwaysExpanded && <Accordion.Indicator isLeading />}
            <span className={VerticalTabBarClasses.sectionTitle}>{title}</span>
          </Accordion.Header>
          <Accordion.Content ref={contentRef} aria-labelledby={sectionId}>
            {React.Children.map(children, (child) => {
              if (React.isValidElement(child)) {
                return React.cloneElement(child, {
                  ...child.props,
                  className: clsx(child.props.className, VerticalTabBarClasses.sectionContent),
                });
              }
              return child;
            })}
          </Accordion.Content>
        </Accordion.Section>
      </Accordion>
    );
  },
);

VerticalTabBarSection.displayName = "VerticalTabBar.Section";
